//
//  PlateModes.hpp
//
//  The vibration modes of a thin circular plate with a free edge — the physics under StruckKit's
//  cymbals: where the modes are, and what a mode's shape is at a given radius (which is how hard a
//  strike there drives it, and how much it moves a contact there).
//
//  Low modes come from PlateModesTable.hpp (exact roots of the free-edge Kirchhoff equations,
//  generated by tools/gen_plate_modes.py). Above that table a cymbal has thousands more; those are
//  placed by the semiclassical (WKB) rule the generator fits to the exact ones (< 1% error in lam),
//  and their shapes use the matching WKB form of the Bessel function.
//
//  Frequencies are proportional to lam^2 (see Cymbal for the material and size that set the
//  constant).
//
//  Framework-free, like ModalBank.
//

#ifndef PlateModes_hpp
#define PlateModes_hpp

#include "PlateModesTable.hpp"

#include <algorithm>
#include <cmath>

namespace Plate {

// J_m(x) by Miller's backward recurrence, normalised with J_0 + 2 (J_2 + J_4 + ...) = 1. Stable and
// accurate for any x (unlike the power series, which loses everything to cancellation by x ~ 30).
inline double besselJ(int m, double x) {
    if (x == 0.0) return (m == 0) ? 1.0 : 0.0;
    const double big = std::max((double)m, x);
    int start = (int)(big + 30.0 + 3.0 * std::sqrt(big));
    start += start & 1;                        // even
    double jp1 = 0.0, j = 1.0e-30, sumEven = 0.0, result = 0.0;
    for (int k = start; k > 0; --k) {
        const double jm1 = (2.0 * k / x) * j - jp1;   // J_{k-1} from J_k, J_{k+1}
        jp1 = j;
        j   = jm1;
        if (std::fabs(j) > 1.0e200) {                // rescale to stay in range
            j *= 1.0e-200; jp1 *= 1.0e-200; sumEven *= 1.0e-200; result *= 1.0e-200;
        }
        if (k - 1 == m) result = j;
        if (((k - 1) & 1) == 0 && k - 1 > 0) sumEven += j;
    }
    return result / (j + 2.0 * sumEven);
}

// I_m(x) by its power series. Every term is positive, so there is no cancellation.
inline double besselI(int m, double x) {
    const double h = 0.5 * x;
    double term = 1.0;
    for (int i = 1; i <= m; ++i) term *= h / (double)i;
    double sum = term;
    const double h2 = h * h;
    for (int k = 1; k < 400; ++k) {
        term *= h2 / ((double)k * (double)(k + m));
        sum += term;
        if (term < 1e-17 * sum) break;
    }
    return sum;
}

// Shape of tabulated mode `p` at radius r (0 = centre, 1 = rim), normalised by its modal mass, so
// it is directly the mode's response to a unit point impulse at r, up to one constant shared by
// all modes.
inline double tableShape(const PlateModeIndex& p, double r) {
    const double edge = (p.c != 0.0) ? p.c * besselI(p.m, p.lam * r) / besselI(p.m, p.lam) : 0.0;
    return (besselJ(p.m, p.lam * r) + edge) * p.invNorm;
}

// --- above the table: semiclassical modes ----------------------------------------------------

// Radial phase accumulated by a wave of angular order m out to the rim (lam > m).
inline double radialPhase(int m, double lam) {
    return std::sqrt(lam * lam - (double)m * m) - (double)m * std::acos((double)m / lam);
}

inline double wkbDelta(double mu) {
    return kPlateWkbDelta0 + kPlateWkbDelta1 * mu + kPlateWkbDelta2 * mu * mu;
}

// The eigenvalue of mode (m, n) by the WKB rule radialPhase = pi (n + delta(m / lam)).
inline double wkbLambda(int m, int n) {
    double lam = std::max((double)m + 1.0, M_PI * ((double)n + 0.5 * m) + 1.0);   // rough start
    for (int it = 0; it < 30; ++it) {
        const double mu = (double)m / lam;
        const double f  = radialPhase(m, lam) - M_PI * ((double)n + wkbDelta(mu));
        // d/dlam of the phase is sqrt(1 - mu^2); delta's own slope is small and left out.
        const double d  = std::sqrt(std::max(1e-6, 1.0 - mu * mu));
        const double next = std::max((double)m + 1e-6, lam - f / d);
        if (std::fabs(next - lam) < 1e-9 * lam) { lam = next; break; }
        lam = next;
    }
    return lam;
}

// WKB shape of a semiclassical mode at radius r, normalised by its (WKB) modal mass. Inside the
// mode's turning radius m / lam the wave is evanescent: a strike there barely drives it, which is
// the reason a bell hit sounds so different from an edge hit.
inline double wkbShape(int m, double lam, double r) {
    const double x = lam * r;
    if (x <= (double)m) return 0.0;
    // Bessel J in its Debye (WKB) form; kappa is held off zero at the turning point (Airy scale).
    const double kappa = std::max(std::sqrt(x * x - (double)m * m), 0.6 * std::cbrt((double)m + 1.0));
    const double J     = std::sqrt(2.0 / (M_PI * kappa)) * std::cos(radialPhase(m, std::max(x, m + 1e-9)) - M_PI / 4.0);
    // Modal mass: the angular integral (2 pi for m = 0, pi otherwise) times the radial one, which
    // for J^2 averaged over its oscillation is sqrt(lam^2 - m^2) / (pi lam^2).
    const double mu   = (double)m / lam;
    const double ang  = (m == 0) ? 2.0 * M_PI : M_PI;
    const double mass = ang * std::sqrt(std::max(1e-6, 1.0 - mu * mu)) / (M_PI * lam);
    return J / std::sqrt(mass);
}

} // namespace Plate

#endif /* PlateModes_hpp */
